\u005b\u006b\u006e\u005a\u004a\u0042\u0078\u0032\u003b\u005a\u0050\u0023\u002b\u0075\u005a\u0058\u005b\u0025\u0039\u002f\u0054\u002a\u0040\u0074\u0022\u0037\u007d\u0025\u005b\u0056\u0052\u003f\u006e\u0068\u0036\u005a\u0039\u0040\u007c\u0047\u0064\u0040\u006a\u005e\u0020\u002e\u004a\u0050\u002b\u007b\u0073\u0063\u0062\u0036\u0059\u006a\u004b\u003f\u0025\u0029\u006d\u0050\u0035\u0026\u007d\u007d\u0038\u0032\u002b\u007d\u006d\u0037\u003c\u0070\u0025\u0063\u003e\u005e\u006c\u007c\u0070\u0041\u0067\u0061\u0071\u0078\u004c\u0068\u0040\u002f\u0036\u0024\u0038\u0021\u0021\u0040\u006d\u0066\u007e\u0066\u004e\u004f\u0062\u0049\u0065\u0047\u0058\u0054\u003b\u0027\u0056\u0065\u0077\u005a\u0029\u0052\u0048\u0051\u0040\u0036\u004e\u0049\u0025\u0071\u002a\u0032\u0063\u0026\u0071\u0039\u0078\u0070\u0065\u0026\u0059\u003c\u0072\u0047\u0049\u007b\u007b\u007d\u0076\u0042\u006d\u0031\u003d\u006a\u0022\u0058\u003a\u0051\u005e\u0034\u0059\u002b\u0049\u0047\u0022\u0037\u0075\u007a\u0032\u0043\u0047\u0029\u006d\u003b\u0026\u0073\u002f\u0077\u0023\u0024\u0029\u0043\u0043\u0027\u0077\u0032\u005e\u0026\u0033\u0065\u002d\u0070\u003e\u0033\u002a\u003d\u0041\u0063\u0055\u0039\u0037\u0072\u0055\u0063\u0027\u007a\u0043\u006c\u0061\u0029\u0039\u0029\u0059\u002f\u0026\u0056\u0036\u0062\u002e\u007a\u0053\u003a\u004c\u0028\u0058\u007b\u0043\u0054\u003c\u007e\u0035\u0039\u002a\u0021\u0069\u003e\u0063\u0062\u002e\u0020\u007d\u0055\u004c\u0030\u005b\u0060\u0052\u007d\u005f\u006e\u0024\u0052\u0077\u0044\u002c\u0053\u0056\u0021\u0047\u006d\u003e\u002a\u0041\u006d\u0045\u0060\u003a\u0079\u0050\u003f\u002c\u006e\u0021\u0035\u0061\u003a\u005f\u0042\u0065\u0035\u0053\u002b\u0074\u0023\u002a\u005f\u0020\u007e\u0040\u0071\u007c\u002f\u0035\u0076\u0051\u0028\u006f\u0060\u0069\u0070\u0043\u006d\u003b\u0046\u0063\u0040\u004d\u007d\u0040\u0039\u0022\u0067\u006f\u0039\u0033\u0020\u0064\u003e\u0028\u0037\u0043\u0052\u0039\u0050\u0061\u002f\u0059\u0070\u0072\u004c\u0069\u0029\u0076\u003a\u0051\u0070\u0032\u0028\u0036\u0029\u002c\u0038\u004b\u0039\u005e\u0033\u0060\u004e\u003d\u0040\u0055\u007e\u003c\u0064\u0038\u003a\u0053\u0050\u005f\u0066\u005c\u004e\u006c\u0035\u0032\u0070\u0026\u0037\u0027\u002d\u0068\u0047\u006d\u0060\u0039\u0067\u0055\u0073\u0041\u0035\u002d\u0028\u0034\u004f\u005a\u0041\u004d\u007a\u0035\u005d\u0057\u0037\u0067\u0074\u0069\u0075\u007a\u002d\u0038\u005f\u0024\u002f\u003c\u0046\u0048\u0051\u0037\u006b\u0056\u0036\u0038\u004e\u004a\u0026\u007b\u005f\u0049\u002f\u0073\u0042\u007a\u0030\u007d\u0023\u003f\u005e\u004e\u0052\u002f\u0035\u0058\u0027\u0041\u006a\u002f\u006a\u005d\u004b\u003e\u005a\u0038\u0038\u0075\u0032\u002f\u0025\u0047\u002b\u0022\u0046\u0027\u005f\u0020\u002b\u007e\u007d\u0031\u0045\u006c\u0038\u0056\u003f\u0078\u003d\u006c\u0041\u005b\u0034\u0033\u004f\u005c\u0054\u0056\u005b\u0070\u003f\u0073\u003f\u002b\u0059\u002a\u0073\u004f\u005b\u002a\u004c\u004b\u0066\u0069\u0043\u0067\u0056\u0041\u004c\u0027\u0027\u0033\u0054\u0077\u0030\u004d\u0055\u0026\u004f\u0071\u0053\u0023\u0068\u0057\u0026\u0066\u002b\u0053\u0051\u0025\u0062\u0042\u0053\u003f\u0046\u0033\u005b\u006a\u0076\u0036\u004d\u0035\u0044\u0050\u0022\u0028\u0076\u0049\u005c\u005d\u0036\u0029\u0052\u004f\u0069\u0030\u005e\u002b\u006d\u0059\u005a\u005f\u0069\u0033\u0025\u0064\u0061\u0042\u004a\u002c\u003d\u0022\u0059\u007d\u0041\u0020\u005b\u0057\u0039\u0052\u0042\u0025\u0075\u006d\u0067\u004e\u0023\u004d\u003c\u0057\u0022\u0060\u004a\u004e\u0048\u0064\u002d\u0032\u0025\u0026\u005b\u0028\u0024\u0043\u0071\u005d\u0021\u0073\u0067\u0045\u002b\u004e\u0026\u002f\u0042\u0031\u0030\u007c\u0071\u005b\u002d\u0078\u0034\u0049\u0023\u0071\u006e\u002d\u0070\u0025\u0069\u0061\u0049\u0040\u0065\u0057\u0045\u0036\u0028\u0033\u0073\u0045\u0056\u0034\u0075\u0071\u004e\u0052\u006b\u005f\u0058\u0077\u0073\u0022\u0063\u003d\u0023\u005c\u0078\u0071\u0026\u003f\u0036\u005b\u005b\u004a\u007b\u003c\u0079\u0027\u0027\u003f\u0040\u0023\u0063\u0061\u002e\u0066\u0035\u006c\u0024\u0053\u0033\u0035\u0030\u002a\u007a\u0065\u0052\u007c\u0046\u002a\u0023\u005f\u003f\u0079\u0042\u005a\u002f\u006a\u003c\u003d\u007e\u0059\u0071\u002a\u0038\u0061\u005a\u005b\u0036\u0054\u0048\u004e\u007c\u0050\u004e\u0055\u005a\u006f\u002b\u005f\u0069\u0068\u0077\u0026\u0070\u0062\u007a\u007a\u006c\u0033\u004d\u004d\u0024\u007b\u0023\u006b\u0047\u0069\u004e\u0057\u005b\u007b\u004e\u002f\u006d\u005e\u004d\u007a\u004b\u0041\u0075\u003e\u007e\u0042\u002f\u0053\u0079\u0077\u0040\u003c\u0040\u0079\u0052\u004d\u0034\u004b\u0064\u005c\u003c\u005d\u0034\u0056\u0022\u0028\u0048\u0079\u004b\u0056\u002a\u0062\u007b\u004a\u0028\u0035\u0025\u0032\u0051\u004c\u0034\u004c\u002c\u0039\u004f\u0058\u004a\u002d\u002a\u0045\u007b\u0071\u005e\u0035\u002c\u0053\u0069\u0075\u007c\u0032\u002f\u0050\u002a\u003e\u0042\u0057\u0066\u0039\u0058\u0060\u0071\u0058\u0062\u0058\u004d\u0059\u0063\u007c\u002a\u005d\u0073\u0050\u0020\u0020\u0037\u0071\u0075\u0041\u0076\u0071\u004c\u0070\u002b\u003e\u0076\u0056\u003e\u005e\u005f\u004a\u0065\u004b\u0020\u003a\u0038\u006a\u006b\u006d\u0029\u004d\u004b\u0040\u007d\u003e\u005d\u0067\u0064\u0057\u002f\u002a\u0056\u0045\u0061\u0064\u0038\u0063\u005c\u0035\u006c\u0049\u0025\u0033\u0079\u004f\u003c\u002a\u005e\u006e\u002d\u003f\u0075\u002d\u007d\u0066\u0073\u0026\u0059\u002c\u005b\u0050\u0022\u007c\u005a\u003b\u0061\u0030\u0034\u0077\u007a\u0055\u003b\u0054\u0034\u006f\u004c\u0061\u0039\u007d\u0027\u002b\u004c\u0045\u0068\u0020\u0049\u0040\u0026\u0075\u002a\u0031\u0025\u0055\u007a\u006a\u0053\u006c\u004f\u0045\u0065\u003c\u0065\u0076\u0073\u005e\u003f\u006f\u0073\u003f\u0031\u0065\u0033\u0054\u007b\u006b\u007d\u007c\u0041\u0066\u004a\u0021\u0042\u0029\u007a\u0026\u005d\u0020\u006d\u005c\u0030\u0050\u0072\u0079\u0053\u0035\u004d\u0034\u004f\u0060\u006a\u0054\u006e\u0035\u0035\u0051\u0048\u0029\u002e\u007c\u0074\u0062\u0027\u0055\u007d\u0028\u007a\u0059\u0064\u0064\u0074\u0068\u0027\u0037\u002b\u0061\u0070\u0069\u007d\u0046\u0030\u0044\u0036\u0037\u0059\u003d\u0067\u006d\u0062\u002d\u006d\u006d\u0054\u0055\u0031\u0076\u0079\u0025\u0047\u0078\u002c\u0038\u0035\u0022\u002f\u006b\u0071\u0066\u0047\u0054\u0041\u005e\u003e\u002c\u0062\u0033\u004a\u005f\u0029\u0039\u005a\u0050\u0034\u0059\u0073\u007e\u0076\u002e\u0055\u005d\u005a\u003c\u0075\u0023\u002a\u0061\u0056\u0067\u0032\u0067\u0069\u0053\u002e\u0058\u005c\u005d\u007b\u004e\u003b\u007e\u0046\u0063\u0023\u0043\u005e\u0076\u0022\u0040\u0060\u0026\u003c\u005f\u0040\u0078\u0077\u006c\u0074\u0022\u0074\u0040\u004f\u0029\u0068\u0064\u0025\u005b\u0044\u006f\u007d\u0071\u0038\u0044\u0037\u004b\u004a\u004d\u003f\u0078\u0047\u005d\u0053\u0063\u0051\u0046\u007a\u0023\u006a\u006d\u0042\u0050\u004e\u0077\u004c\u0045\u005a\u006b\u0044\u0030\u006e\u005b\u0035\u007e\u0060\u0041\u0031\u0030\u007e\u003e\u005a\u004d\u0031\u006b\u0063\u0044\u006d\u004e\u0062\u0069\u006f\u006e\u003f\u0034\u0067\u0039\u0040\u0074\u002a\u0040\u0041\u005b\u0039\u0056\u0067\u0044\u0069\u0064\u003a\u0025\u0054\u004f\u0039\u002b\u003d\u0072\u0032\u0050\u002d\u004c\u0079\u0054\u0032\u004d\u002c\u0054\u0055\u0037\u0060\u0031\u002c\u0077\u0074\u0041\u0078\u0071\u0049\u0064\u0022\u0025\u0034\u0071\u0035\u0026\u0047\u0056\u006c\u0046\u0066\u0059\u005e\u007b\u007a\u0026\u0051\u006d\u004e\u0049\u003b\u0043\u002a\u0049\u0031\u003d\u0041\u006d\u0064\u0067\u0027\u002b\u003a\u002d\u0056\u0051\u0049\u002d\u004f\u007b\u0073\u003c\u0026\u0030\u006e\u004f\u0043\u003e\u0036\u005b\u0028\u006f\u006d\u0069\u0033\u0031\u007d\u007d\u0058\u0058\u0029\u0028\u0054\u0030\u0058\u0070\u0029\u005c\u0053\u0053\u003c\u0021\u006f\u0040\u005d\u004e\u0028\u0040\u007e\u0063\u0048\u0031\u004c\u005e\u0029\u006b\u005f\u003e\u006f\u0067\u0069\u0024\u0039\u0078\u0044\u005b\u005c\u006a\u0030\u006b\u002c\u0041\u007e\u0075\u0060\u0075\u004c\u0063\u0064\u004f\u003b\u0041\u0050\u0036\u0058\u0020\u002a\u0034\u0065\u007b\u0053\u0055\u0065\u0038\u0069\u002a\u0030\u0072\u0051\u004f\u003f\u0074\u007d\u0039\u0050\u0043\u0041\u0046\u0051\u005b\u0059\u0054\u0071\u002b\u0066\u0045\u006e\u0029\u002a\u0074\u0072\u006b\u0045\u005c\u0036\u005e\u003d\u0063\u0049\u004f\u0044\u002c\u0020\u0049\u007c\u0021\u0039\u0074\u0030\u0040\u007d\u0063\u0042\u0022\u0043\u0036\u0069\u0058\u0074\u0025\u0055\u004f\u0076\u0032\u007b\u0024\u005b\u005b\u004c\u0045\u007b\u0066\u004b\u0049\u0036\u0051\u007b\u002a\u005d\u007c\u0067\u0068\u002b\u002d\u003b\u0060\u0050\u0045\u003c\u004e\u003d\u0021\u0024\u0076\u0039\u0056\u004f\u0057\u0023\u007a\u0039\u005f\u002c\u0058\u0067\u005f\u006b\u006a\u0059\u0049\u0078\u0046\u007b\u0057\u002e\u0064\u005e\u0056\u0049\u002f\u0034\u0072\u0032\u005f\u0049\u004a\u0078\u006a\u0069\u002a\u0023\u0035\u0073\u0029\u0041\u005f\u0070\u002a\u0060\u007b\u0040\u003e\u004c\u0021\u005d\u003d\u0023\u004f\u0025\u0073\u0048\u002e\u0055\u005a\u007a\u006f\u007c\u0030\u004b\u004d\u0040\u0057\u006b\u002b\u003f\u0021\u007d\u0052\u0079\u0079\u0021\u002c\u006d\u002f\u003d\u0021\u007b\u004e\u003a\u0020\u004f\u0050\u004d\u004b\u002d\u0033\u0055\u007a\u002b\u0047\u0076\u005d\u0072\u004f\u0025\u006d\u004c\u0041\u0053\u0036\u0032\u0025\u002f\u0074\u006b\u0072\u0029\u0028\u0054\u003c\u0048\u0046\u004f\u0067\u0057\u0028\u007d\u0045\u0069\u004a\u0051\u0041\u0024\u0027\u003d\u002b\u0041\u0023\u005f\u0059\u002a\u0071\u0043\u0031\u003b\u0046\u0031\u0074\u0044\u002b\u0051\u003e\u002d\u004d\u002b\u0032\u003d\u005e\u0077\u0068\u0046\u0053\u0070\u0076\u0025\u006e\u0050\u0070\u006c\u0072\u0056\u0022\u0060\u0045\u0025\u0046\u0061\u004c\u0037\u0079\u006d\u0036\u0066\u0077\u003d\u0043\u0067\u0076\u0045\u0038\u0071\u0066\u0034\u0031\u0045\u0073\u0041\u002b\u003f\u0038\u004e\u004f\u0021\u005d\u0036\u0025\u004e\u0045\u003b\u0041\u0047\u002c\u0056\u006b\u007c\u0042\u0064\u0034\u003a\u0062\u0032\u005c\u002e\u0068\u005d\u0033\u0037\u0027\u0023\u005d\u005b\u0078\u0063\u004f\u002b\u0052\u0037\u002a\u0029\u006b\u0040\u004d\u0059\u0027\u005c\u0075\u002a\u0033\u0056\u0058\u0056\u0071\u0065\u0044\u0031\u0035\u0038\u0030\u0020\u007a\u0021\u0040\u0073\u004a\u004b\u0078\u0079\u0022\u0077\u002c\u003a\u0061\u0057\u0063\u002b\u003f\u0037\u0072\u002d\u0048\u0025\u0029\u0037\u003a\u005d\u003e\u0043\u007e\u002a\u0045\u0069\u005b\u006a\u0052\u007d\u0040\u002d\u003d\u0040\u005b\u0030\u003b\u004a\u0057\u0049\u002e\u0021\u0048\u0027\u004d\u005b\u007d\u0029\u0078\u0049\u0049\u0076\u0023\u0066\u0053\u0051\u006c\u0062\u0065\u0034\u004f\u006c\u0060\u003d\u0036\u007a\u0043\u0036\u0064\u006e\u0034\u0053\u0069\u006d\u0050\u005d\u0028\u0043\u0024\u004c\u005a\u005e\u0057\u0069\u0040\u0050\u0055\u006c\u005e\u006d\u004b\u004a\u004f\u0046\u002b\u0022\u004c\u006d\u002c\u0048\u0051\u0042\u0031\u006c\u004a\u004e\u006f\u004b\u002a\u0058\u0052\u004a\u003d\u003b\u005c\u0031\u0046\u0036\u002f\u0054\u0060\u0053\u0030\u0059\u004d\u0053\u0075\u0076\u0055\u0053\u005f\u0058\u0049\u0033\u002a\u006e\u005e\u0031\u003f\u006b\u007b\u0021\u0077\u0038\u006d\u006a\u0031\u0028\u0070\u0030\u0023\u0071\u0050\u0035\u002d\u002e\u004b\u0062\u0070\u0036\u0061\u004e\u0066\u003c\u003e\u007b\u006f\u006e\u0034\u0033\u0074\u0073\u006e\u0061\u0025\u002c\u0073\u0074\u002b\u002d\u0059\u0026\u0054\u0072\u0039\u004c\u0039\u0075\u004f\u005f\u0021\u004f\u0061\u0066\u0061\u0073\u0064\u003e\u0049\u0071\u007a\u005b\u0035\u0034\u0065\u0044\u0028\u007e\u003b\u0060\u0032\u0068\u002b\u0042\u004e\u0066\u0056\u0033\u0046\u004b\u0032\u0055\u006d\u0066\u0042\u006f\u0062\u006d\u0046\u0078\u0058\u0062\u005b\u0021\u002b\u0051\u0077\u0031\u004a\u003b\u0024\u002d\u005c\u004b\u007d\u0025\u0073\u0028\u0044\u0052\u0062\u0021\u006e\u0050\u0079\u0039\u0039\u0039\u0030\u0063\u0074\u0055\u006c\u0074\u0074\u0074\u006b\u0022\u0047\u0052\u0060\u0025\u0030\u0067\u0065\u0033\u0035\u004f\u0033\u0029\u002a\u005b\u006a\u0021\u0052\u005b\u0078\u007e\u0078\u007c\u0071\u006d\u0037\u0061\u003f\u004e\u007e\u003a\u0043\u002d\u0029\u0041\u004a\u0077\u0030\u003d\u006d\u0022\u0078\u004a\u0061\u0044\u003e\u0072\u0051\u005c\u002e\u0034\u0023\u0030\u003a\u0051\u0074\u0023\u0031\u007c\u006e\u0055\u003d\u007a\u005b\u0074\u0020\u0075\u004a\u0070\u0037\u0048\u006f\u005e\u0024\u002a\u0050\u005e\u0076\u0026\u0076\u0069\u0076\u0037\u0042\u002a\u0029\u005e\u0052\u005d\u0047\u003a\u0072\u0044\u0061\u004a\u002e\u006b\u002c\u0040\u0073\u002f\u006d\u0042\u0049\u0020\u0039\u0063\u0050\u0073\u006e\u0068\u0064\u007d\u005c\u0044\u0038\u0046\u0033\u0070\u0071\u005b\u004f\u0069\u0057\u002a\u0030\u0056\u0040\u004f\u0037\u005e\u0032\u0020\u0062\u0034\u005a\u0055\u004e\u0033\u0067\u0036\u0044\u0028\u004e\u0041\u0075\u0079\u002f\u002b\u0034\u0051\u0040\u007e\u0054\u0034\u0059\u0046\u0072\u0057\u006a\u007a\u0065\u007c\u0026\u002b\u0069\u0036\u0060\u0061\u0067\u0051\u004d\u0062\u004a\u0063\u0074\u0069\u003c\u0043\u007c\u004f\u0053\u006e\u0062\u007c\u003d\u002a\u0023\u0066\u005c\u003b\u005a\u0050\u005f\u0043\u0031\u003c\u0034\u007c\u007d\u007b\u0049\u0040\u007e\u002c\u0047\u0057\u0070\u002a\u0034\u006d\u0041\u0020\u0059\u0065\u005a\u004c\u0061\u002c\u0051\u0056\u0067\u0075\u006a\u006a\u006a\u0056\u002d\u007a\u004c\u0050\u0048\u003e\u0078\u0072\u0075\u002c\u0074\u0025\u0078\u006e\u006c\u003b\u0065\u0055\u002f\u007c\u0042\u0078\u004d\u005a\u003a\u0021\u0037\u006f\u003c\u0058\u0073\u0072\u007e\u006c\u0022\u0031\u003e\u004e\u0025\u003a\u0077\u0074\u007e\u002f\u005c\u0036\u0045\u006f\u004a\u004d\u0065\u002a\u0076\u0057\u0024\u0042\u0026\u0052\u0073\u005b\u004d\u007d\u0072\u0021\u002e\u006e\u0062\u0073\u007c\u0038\u0046\u0021\u0064\u006b\u0024\u0077\u005a\u0025\u005b\u002a\u0066\u0030\u0076\u0051\u0030\u0043\u007e\u0058\u0025\u007d\u006e\u003e\u003e\u0073\u0034\u007e\u0054\u0073\u003f\u004e\u006f\u005c\u0023\u0074\u0071\u0027\u0050\u0056\u0059\u004c\u002a\u007d\u0023\u005c\u0056\u0030\u0032\u004c\u0064\u0069\u0070\u0041\u006b\u0061\u002b\u0025\u0042\u003c\u0034\u0053\u0051\u002e\u0066\u0057\u0023\u0059\u0070\u0038\u0060\u006a\u0050\u0067\u0036\u0060\u0025\u006a\u006a\u0051\u002c\u0029\u0053\u003e\u0049\u0039\u002a\u005a\u0046\u0074\u0040\u004b\u007e\u005d\u0032\u0035\u003e\u003b\u003b\u0059\u0043\u006c\u0052\u0028\u0063\u0048\u006b\u0025\u0020\u0072\u0052\u005f\u0041\u0058\u0069\u0026\u0044\u0046\u0051\u0038\u006a\u003e\u007c\u0023\u0022\u0062\u0064\u003d\u0057\u0063\u0043\u0050\u0028\u003e\u0047\u0060\u002a\u0033\u0057\u0049\u007a\u0079\u004c\u007c\u0078\u0044\u004b\u004a\u0073\u0036\u005c\u0025\u0075\u0075\u007a\u007c\u0026\u0063\u0046\u0071\u003b\u005e\u0025\u006c\u0034\u0050\u0048\u0039\u005a\u0030\u0075\u004a\u0074\u0038\u0029\u0053\u006a\u006c\u0027\u006c\u0027\u0075\u0075\u0029\u006c\u0029\u0027\u007b\u0072\u0039\u0020\u0036\u0061\u0040\u006c\u0041\u004b\u007b\u0076\u006b\u0041\u0072\u0030\u0044\u005c\u0079\u002d\u0040\u0070\u003d\u0047\u0058\u0052\u005d\u0024\u003e\u0044\u0022\u0021\u0049\u0057\u0031\u0078\u003d\u0040\u0078\u0027\u0024\u003f\u006a\u006d\u0064\u003d\u002b\u0048\u0071\u0027\u0068\u0067\u0026\u0073\u005c\u0066\u0036\u004e\u0040\u002e\u0073\u0040\u003f\u003a\u0064\u004d\u0049\u0022\u0030\u005b\u0025\u0029\u0055\u0024\u006a\u0072\u002a\u0064\u0062\u0060\u004a\u0035\u0023\u002b\u0069\u005c\u0051\u0033\u0039\u002a\u0063\u0076\u0030\u005a\u0038\u0025\u0052\u007c\u0077\u0028\u006f\u003a\u0066\u0049\u0074\u0075\u0059\u0030\u0073\u0061\u0044\u0035\u0059\u0057\u0043\u0028\u0055\u004b\u0049\u0043\u004e\u004e\u0042\u002d\u0058\u0046\u0033\u0053\u005f\u006a\u0028\u0052\u0024\u006a\u0073\u004a\u0052\u003c\u005c\u0020\u0023\u006a\u0027\u0066\u0056\u002c\u0056\u0036\u005d\u002d\u0072\u006f\u0073\u0065\u0033\u006b\u005a\u0033\u005f\u0072\u0063\u0034\u0065\u002f\u0073\u0075\u0050\u0058\u005c\u0070\u002f\u006c\u0053\u0057\u0022\u0071\u006a\u0057\u004c\u0064\u0077\u0065\u006a\u0076\u0037\u007c\u0074\u0048\u0065\u0060\u0049\u0030\u002f\u0050\u004b\u0022\u0078\u0079\u007d\u0059\u004e\u0048\u0078\u0049\u0060\u0020\u0052\u006f\u006b\u002c\u0068\u0042\u006c\u006d\u0070\u0033\u005e\u0056\u004c\u006d\u0052\u0023\u0060\u0067\u0024\u0054\u005c\u0020\u0055\u002c\u0047\u0050\u002a\u0059\u0048\u0070\u006e\u0048\u0064\u005d\u0028\u007e\u0058\u0052\u006a\u0048\u0031\u0036\u004e\u0060\u0047\u0074\u0021\u0035\u004f\u005b\u0039\u0064\u004f\u0020\u0043\u0070\u0047\u0044\u0075\u0051\u004d\u0031\u002d\u0052\u003a\u0040\u0079\u005e\u0059\u002b\u0072\u0058\u0063\u007d\u0073\u0029\u0070\u0036\u0054\u0064\u002c\u0067\u004f\u002e\u004f\u0045\u0047\u003c\u0029\u0065\u007a\u0074\u0038\u0051\u0027\u0061\u004d\u004b\u0045\u0040\u006c\u004c\u0052\u005c\u0075\u0054\u007c\u003f\u0078\u0049\u0049\u0035\u0023\u0027\u007c\u0068\u0076\u002f\u0054\u0037\u0038\u0075\u0027\u0047\u0061\u006f\u002e\u005e\u005d\u0026\u003c\u0065\u0060\u0070\u005d\u002d\u004b\u0077\u0036\u0023\u0073\u005d\u003e\u0064\u0072\u0075\u004e\u007b\u0036\u005f\u0069\u007e\u0055\u0033\u0027\u0028\u003e\u005c\u0047\u003e\u0079\u005a\u002d\u0031\u0020\u002c\u005c\u0023\u0061\u006e\u0047\u0077\u006b\u004a\u0038\u0066\u003d\u0065\u0049\u002b\u002f\u0053\u0073\u0035\u0066\u0034\u002d\u0035\u0061\u0059\u0071\u0062\u003f\u0067\u002c\u005b\u0054\u0064\u0063\u003d\u004a\u007d\u0053\u0020\u0067\u006c\u0039\u005a\u004e\u0068\u0071\u0058\u0052\u005d\u003e\u0055\u0055\u0032\u0066\u0025\u0056\u003b\u0068\u0048\u0031\u0030\u0057\u0037\u0065\u0072\u0064\u002b\u0026\u006d\u002c\u0072\u0058\u0033\u0026\u0052\u0062\u006f\u005e\u007c\u0073\u0021\u0063\u0072\u0035\u0043\u0031\u006f\u003d\u0049\u0024\u0034\u0068\u0072\u0033\u005c\u0062\u003d\u0078\u0021\u003b\u0053\u0063\u007b\u0041\u004b\u0059\u0054\u002e\u0050\u0030\u005d\u0039\u004a\u005e\u0054\u0061\u0064\u0036\u0043\u006a\u003e\u0070\u0038\u0065\u006a\u007a\u0032\u002a\u0058\u004d\u0056\u004b\u0049\u002d\u006c\u004c\u005b\u0053\u0069\u0073\u0055\u0044\u002a\u003d\u0034\u0036\u0067\u0036\u0060\u006b\u0030\u006b\u004a\u0031\u007d\u002b\u0027\u006e\u004c\u0074\u0022\u0050\u0075\u007e\u0050\u0052\u0054\u0042\u0043\u0070\u005b\u0044\u0064\u0063\u0050\u0064\u0044\u0046\u0025\u003b\u004e\u0062\u0047\u006e\u0072\u0029\u0073\u0053\u0066\u0034\u0020\u0058\u0042\u003e\u002a\u0028\u0071\u0030\u0032\u007d\u0053\u0038\u0033\u0059\u0029\u0052\u0065\u0039\u0043\u0049\u0068\u0024\u005d\u0066\u0020\u003b\u0079\u005e\u0031\u0037\u005c\u0026\u0046\u007a\u005a\u0043\u002a\u0064\u0036\u0027\u0067\u0033\u002c\u0027\u0039\u0069\u007e\u003a\u004f\u0055\u0048\u0078\u0053\u004b\u0062\u004f\u002c\u0041\u0036\u007a\u005b\u0061\u0061\u0055\u0067\u0024\u0030\u0026\u0026\u0045\u005f\u003d\u0026\u005e\u0036\u005f\u0038\u0024\u0050\u0023\u007c\u0030\u0021\u003b\u0068\u0045\u004a\u0027\u0075\u0071\u0043\u006f\u0059\u004b\u0033\u0037\u007c\u005a\u0058\u0056\u0076\u007d\u0042\u0046\u0031\u0050\u0045\u0046\u0062\u0058\u0039\u0052\u002e\u007d\u0045\u007e\u0078\u0058\u0068\u0036\u0024\u007c\u003a\u0077\u004f\u0046\u0031\u007e\u004b\u0027\u006b\u0033\u0033\u0040\u006c\u003d\u0036\u0058\u005d\u0038\u0078\u0048\u0035\u0037\u0073\u0021\u0039\u0075\u002d\u0075\u0064\u0028\u0063\u0031\u0024\u0045\u0056\u0074\u006b\u0021\u0043\u004a\u003b\u0023\u002a\u006b\u0071\u007e\u007b\u0052\u007c\u003b\u0059\u0066\u0048\u0032\u0065\u003c\u0076\u0025\u0024\u0078\u0060\u0076\u0034\u004b\u007a\u0022\u006f\u0074\u0051\u0050\u0065\u007a\u005e\u0045\u0042\u0079\u007d\u006e\u0059\u0049\u007e\u0059\u0075\u0075\u0049\u004a\u0021\u005f\u0028\u0071\u0067\u0044\u0047\u0023\u0048\u0037\u0021\u0039\u0040\u0033\u0050\u004c\u0057\u006c\u0044\u0023\u0047\u0070\u003e\u0063\u0040\u007a\u004a\u005d\u0051\u003b\u0042\u002d\u0057\u0042\u002a\u0064\u0051\u0063\u0038\u004a\u0056\u007a\u0020\u003b\u0047\u0030\u005c\u0074\u0055\u0054\u0060\u0050\u0027\u002b\u0057\u0063\u006c\u0026\u005f\u002d\u002f\u003a\u0036\u003d\u0033\u0056\u006c\u0054\u0040\u0056\u003a\u0024\u002c\u0062\u0065\u0051\u006b\u003c\u006c\u0073\u0035\u0069\u0052\u007a\u0026\u0067\u007d\u007c\u0057\u0046\u003e\u0063\u0048\u002f\u005c\u0064\u005d\u007b\u0027\u006e\u0035\u0034\u003e\u004f\u0076\u0051\u0076\u0069\u0054\u007c\u0030\u005a\u0028\u0030\u006c\u005e\u006a\u0027\u004d\u0043\u003f\u0021\u003d\u0070\u006b\u002e\u006e\u004b\u0064\u0045\u0072\u005d\u0053\u007c\u0033\u0021\u003f\u0079\u0037\u0031\u0041\u004c\u0027\u0032\u0041\u003f\u0076\u0021\u0032\u0023\u0020\u003c\u004d\u0058\u0034\u0067\u0056\u0064\u005d\u0078\u002a\u0075\u0045\u0065\u0051\u0061\u005b\u0029\u0048\u0035\u0034\u0034\u0027\u0034\u006c\u0074\u0025\u0037\u0071\u005d\u0026\u0044\u0060\u0052\u0040\u0026\u0070\u004b\u0038\u006a\u0058\u002b\u006e\u002b\u004e\u0036\u002f\u0027\u0030\u002b\u007b\u0058\u0074\u005a\u004f\u0062\u0068\u003b\u007d\u005b\u0076\u004d\u003f\u004e\u0058\u0038\u006f\u0045\u0044\u0068\u0057\u0071\u0040\u005d\u0067\u002e\u0067\u0046\u004d\u0068\u0062\u0041\u0027\u0021\u003a\u007a\u0071\u0052\u0055\u0020\u0076\u0052\u007d\u0041\u0062\u007b\u0077\u0053\u002d\u0075\u0052\u0039\u0067\u005e\u005d\u002a\u0066\u0059\u0079\u002c\u0027\u005b\u007c\u0073\u0033\u0065\u004a\u0057\u0062\u0035\u0059\u0055\u0060\u004f\u002c\u0046\u002c\u007b\u007d\u004b\u0028\u006e\u0064\u0022\u006e\u0021\u005f\u0070\u003b\u007a\u0029\u0045\u0061\u0074\u007c\u006c\u0059\u0054\u0065\u002a\u003a\u0021\u0063\u0030\u007a\u0024\u0073\u0030\u0058\u002b\u0027\u0078\u0063\u004f\u0022\u004b\u002a\u0026\u0050\u007d\u006e\u0075\u0022\u0027\u005f\u0035\u0034\u0058\u0058\u0028\u002f\u005b\u0024\u003c\u0053\u005c\u0072\u005a\u0052\u004e\u0023\u0034\u0020\u0069\u0069\u0054\u0033\u0043\u0069\u006d\u005f\u0020\u0033\u003f\u0034\u0062\u004c\u003f\u0067\u0035\u007b\u0061\u0065\u0024\u0048\u0073\u0052\u0053\u002e\u0031\u0048\u0024\u0025\u0062\u0050\u0060\u002a\u0023\u006e\u0032\u0050\u003b\u0057\u006a\u002f\u0023\u0046\u0054\u0059\u0062\u0049\u004a\u006f\u002d\u0063\u0074\u0057\u0061\u0028\u0028\u004a\u006a\u0065\u003b\u005d\u0041\u0062\u0060\u007a\u003d\u0036\u004b\u0059\u003b\u007d\u002b\u004b\u002f\u0076\u0055\u005e\u003d\u002f\u0067\u005c\u0058\u003e\u002a\u0069\u0049\u005b\u0027\u0043\u0028\u0055\u0051\u0058\u0025\u0076\u0026\u002f\u0050\u0066\u0047\u006f\u003b\u0066\u0037\u005f\u003a\u007e\u0068\u006e\u0060\u007b\u0048\u0074\u002f\u004b\u0062\u0075\u0072\u0029\u005c\u002c\u005e\u0065\u0065\u005a\u0049\u003e\u0074\u0057\u005e\u003d\u0025\u0048\u0054\u0024\u0034\u0040\u0021\u0054\u0023\u003b\u007c\u0053\u0020\u0059\u002c\u0063\u0069\u0072\u0062\u0023\u0067\u0042\u0045\u0052\u007b\u0038\u0027\u003c\u003f\u0075\u005a\u0062\u003e\u007b\u0067\u0023\u0077\u0069\u0028\u003f\u0071\u0032\u0026\u0020\u003b\u007e\u0030\u0064\u007a\u0042\u005c\u0038\u006f\u0072\u0062\u002d\u0079\u007e\u0071\u0049\u0067\u0075\u0053\u006d\u0058\u0062\u006a\u0024\u0053\u0045\u0068\u0036\u005c\u0073\u002d\u0076\u0049\u003d\u0051\u003f\u004d\u003b\u0051\u004c\u0039\u0037\u005b\u0054\u0070\u002c\u0029\u0070\u0043\u004a\u0022\u005a\u0024\u0060\u0044\u005f\u002d\u0059\u0032\u003c\u0037\u0074\u0032\u0044\u0045\u0062\u003c\u0032\u0053\u003d\u007b\u0025\u0076\u0033\u005d\u003e\u0036\u0027\u0070\u005d\u0079\u0042\u0027\u003e\u0027\u0048\u0025\u0047\u0058\u005a\u0037\u005e\u0025\u002f\u0027\u0071\u002e\u005f\u0078\u006a\u0036\u002b\u0076\u004a\u0053\u0043\u0059\u0071\u0030\u003a\u0058\u0071\u0070\u0063\u004b\u003e\u002d\u002c\u0051\u005d\u0063\u006f\u002e\u005f\u005d\u0047\u006e\u0020\u0034\u0046\u0052\u002a\u0055\u0049\u0063\u0061\u0066\u003a\u007e\u0031\u007d\u0067\u002e\u004c\u004c\u007b\u0042\u002a\u0033\u0051\u0069\u005b\u005b\u0066\u0036\u0078\u0037\u0070\u004b\u004d\u002a\u004d\u0032\u0065\u0025\u0029\u003b\u0077\u0035\u0065\u0070\u007e\u0055\u0067\u0063\u0021\u002a\u003b\u0059\u002b\u0062\u002a\u005a\u002e\u002c\u007a\u002d\u0076\u007b\u0075\u004c\u003f\u0068\u0051\u0053\u0071\u003f\u003b\u0067\u0027\u006b\u0030\u0063\u003c\u006b\u0067\u0070\u003e\u0071\u0033\u0067\u0035\u0050\u0067\u005a\u006a\u0070\u0056\u0029\u006d\u0046\u0033\u0037\u0031\u0078\u0043\u0052\u0044\u006b\u0079\u0046\u0045\u0062\u004f\u0070\u007e\u0055\u003c\u007b\u006d\u0074\u0032\u0029\u004b\u0044\u002a\u0074\u005f\u0076\u0078\u003f\u003d\u0069\u007c\u005e\u0068\u0074\u005c\u002d\u0076\u0058\u002b\u0070\u0070\u0062\u0027\u0043\u0065\u0075\u0029\u0063\u005b\u003d\u0069\u0034\u0021\u0062\u0044\u0047\u004e\u003f\u0040\u0038\u007c\u003c\u0070\u0057\u0049\u0062\u0061\u0035\u0050\u004c\u006d\u0039\u004d\u0061\u0034\u0077\u003f\u003c\u004b\u0048\u0075\u006f\u0049\u0060\u0074\u0077\u003c\u0033\u0045\u0079\u0075\u0023\u0059\u0022\u0021\u0070\u0076\u0053\u0038\u0074\u003c\u002e\u0072\u007a\u003f\u0032\u0067\u003d\u002d\u0020\u0021\u0030\u005c\u006a\u0022\u004a\u0024\u0042\u002e\u005a\u007e\u0023\u0027\u0050\u0050\u006d\u0052\u0039\u0063\u0058\u0051\u007c\u0059\u005b\u007d\u0073\u0051\u0067\u0059\u004a\u0069\u004f\u0024\u0072\u007b\u006e\u0057\u0062\u0036\u0047\u006a\u0024\u005f\u007e\u0062\u003c\u0044\u0058\u002d\u0033\u0028\u0077\u0075\u007b\u0078\u004c\u0035\u007b\u0038\u004b\u0075\u0036\u002b\u0061\u0050\u006c\u007c\u0029\u007c\u005e\u006b\u0043\u0034\u006b\u0037\u0033\u002f\u002d\u0050\u0055\u0062\u0062\u0022\u005a\u007e\u007b\u0052\u004d\u0040\u0023\u005f\u003f\u003b\u0043\u0027\u0077\u0067\u0064\u0046\u004a\u0050\u0021\u0030\u006b\u003c\u005a\u005e\u0030\u0038\u005c\u005c\u0070\u0061\u0070\u0070\u0065\u007d\u0021\u0039\u0059\u0028\u005a\u0041\u0063\u003e\u005b\u0054\u0039\u0061\u006c\u0042\u006a\u0032\u002a\u0051\u0035\u0046\u0064\u0033\u0060\u0074\u0068\u0069\u005b\u0079\u007e\u006a\u0074\u0040\u0046\u002b\u002c\u0058\u003d\u0079\u0072\u0076\u005a\u002c\u003e\u0045\u007b\u0067\u003a\u0034\u0049\u0059\u0034\u002e\u0063\u0070\u0020\u0032\u0049\u0025\u0065\u0052\u0069\u0023\u0070\u0021\u0024\u003b\u005d\u0072\u0070\u0062\u005f\u0051\u003c\u0044\u003f\u003e\u003a\u005e\u006b\u0051\u0050\u0077\u002e\u0077\u002f\u006e\u0023\u002b\u0040\u0050\u003e\u0029\u005b\u0043\u003a\u003a\u006a\u0061\u004c\u0034\u005c\u005a\u004c\u003a\u002c\u0066\u007c\u0030\u0068\u0068\u0046\u005a\u0028\u004c\u0067\u0067\u004a\u005b\u0036\u006d\u0064\u003f\u007d\u0027\u0026\u0050\u0042\u0048\u0028\u0044\u0075\u003c\u0077\u0078\u0061\u0038\u004b\u003c\u0025\u005c\u0075\u0053\u0078\u0062\u0059\u002b\u005f\u0073\u0022\u005c\u0067\u0044\u005f\u0068\u0068\u0062\u0036\u0049\u002f\u005b\u0062\u004b\u006e\u003b\u0030\u0021\u0066\u007b\u006d\u0039\u0077\u006a\u0024\u0064\u005d\u0021\u0049\u004e\u0033\u0067\u0021\u0051\u007c\u0054\u0053\u0024\u0048\u003a\u0062\u0044\u0055\u0076\u0045\u005c\u0058\u005b\u0034\u0034\u0039\u0073\u004a\u002e\u0058\u003e\u0052\u0077\u0045\u003b\u004e\u0027\u0038\u0024\u0065\u0073\u0060\u0022\u006e\u003a\u0034\u006e\u0023\u005c\u007b\u003c\u0033\u0079\u0039\u0071\u0064\u0070\u0020\u006f\u004d\u003a\u0047\u007d\u0020\u006e\u0073\u002c\u0074\u004e\u0078\u0075\u0064\u0020\u0066\u0078\u004d\u005d\u0031\u0075\u006a\u005d\u004d\u0062\u002f\u0063\u0077\u0075\u0056\u0042\u003e\u0049\u0056\u005c\u0069\u0070\u005e\u0028\u0076\u0023\u002f\u004d\u005a\u0042\u0079\u0078\u007c\u0066\u002c\u0076\u0055\u0053\u0058\u003b\u0038\u007d\u0057\u0029\u0052\u0021\u004f\u0025\u0077\u006c\u002e\u006c\u007a\u0028\u0047\u0067\u0041\u0049\u0073\u006e\u0043\u0061\u0064\u003f\u003a\u005d\u0064\u005d\u003d\u0020\u002d\u004b\u0059\u0025\u0072\u005a\u002c\u0046\u0034\u0024\u0043\u0062\u002f\u0078\u0078\u0071\u005e\u006c\u0064\u0020\u0046\u0022\u0034\u003a\u0022\u007c\u0059\u0034\u007c\u0073\u0028\u006b\u0067\u0060\u002a\u002f\u0022\u005f\u0034\u0055\u0062\u0064\u0066\u003d\u003c\u007c\u0069\u0068\u0027\u0073\u0024\u0069\u0041\u0065\u006b\u005c\u0060\u0041\u0050\u005d\u002a\u0054\u0038\u0024\u0069\u004c\u007c\u007b\u005f\u0028\u002b\u0061\u005e\u006b\u0048\u004e\u0071\u002f\u007c\u0075\u0035\u007c\u006b\u0049\u0046\u0064\u0035\u0020\u003d\u0054\u0040\u002a\u0076\u005d\u006d\u006e\u002b\u0076\u005e\u005c\u0045\u0076\u007a\u0056\u006d\u002d\u003a\u0020\u005f\u0071\u002c\u0035\u0067\u007d\u0065\u0045\u003f\u0074\u0045\u006a\u0052\u002c\u004d\u0061\u007e\u002b\u006a\u0025\u0061\u0035\u0077\u0027\u005b\u004d\u007d\u0030\u0072\u0034\u0072\u003c\u003e\u0050\u0032\u002e\u005b\u007d\u0040\u0055\u007a\u003f\u006d\u007b\u0073\u0073\u007d\u0032\u003a\u007a\u0048\u0030\u0020\u0076\u0021\u0045\u007c\u006c\u006a\u0063\u0030\u002c\u003e\u006a\u0048\u002f\u004f\u0065\u0050\u004f\u0069\u0072\u007e\u0041\u006c\u0069\u0073\u0021\u006b\u003f\u007b\u0030\u0042\u0031\u0064\u0076\u0027\u007a\u007b\u007c\u003b\u0039\u0052\u006d\u0039\u006f\u0071\u005a\u0070\u005b\u002d\u0031\u0044\u004e\u007d\u0038\u0072\u005f\u002a\u0047\u007a\u007b\u005d\u004c\u0034\u0026\u0060\u0065\u002b\u0029\u006e\u0020\u0057\u0054\u002d\u0021\u0058\u006a\u0027\u006c\u0065\u0073\u0033\u002c\u003b\u006e\u0032\u007c\u002a\u0051\u0044\u0047\u0068\u002b\u0072\u006e\u0072\u0030\u0045\u0027\u0039\u002b\u0042\u0050\u0049\u007e\u005b\u0057\u0024\u002e\u004f\u002b\u004f\u0049\u0059\u005f\u0062\u0074\u0033\u007b\u003a\u0049\u0050\u004a\u004b\u0074\u0069\u003f\u0046\u0028\u006c\u0078\u0065\u0063\u006a\u005b\u006a\u0042\u005a\u0038\u0059\u0023\u0067\u006b\u0049\u007e\u002a\u0053\u0045\u0059\u005a\u0024\u003f\u007e\u002f\u0035\u0054\u0066\u0055\u006a\u0069\u0038\u0037\u0070\u0056\u006a\u0063\u0072\u0022\u005b\u006f\u0032\u0050\u0045\u0041\u006e\u0020\u0044\u003c\u002c\u0023\u0023\u005e\u0045\u006c\u0029\u0066\u006d\u0071\u0033\u0060\u0034\u003a\u007d\u0077\u0038\u007c\u006c\u0026\u0031\u003f\u0045\u007c\u0061\u005b\u0021\u0035\u0020\u0033\u0039\u004e\u002e\u0058\u0035\u002c\u0034\u0057\u004a\u0060\u0030\u006e\u0078\u0033\u0026\u0078\u0037\u006b\u004b\u0030\u005f\u0062\u003e\u0062\u002a\u0028\u0071\u0076\u0072\u005a\u0046\u002e\u0046\u0053\u0027\u0021\u0058\u0075\u0022\u0040\u0063\u0037\u0043\u007b\u003b\u0076\u0057\u002b\u005e\u0022\u004a\u0053\u006b\u0047\u006d\u0040\u0048\u005a\u005f\u0076\u005c\u004f\u0045\u005c\u0044\u0020\u0021\u007b\u0072\u002f\u0049\u0069\u006f\u006f\u0034\u002c\u0042\u0078\u0062\u002f\u005b\u004e\u003e\u0022\u0077\u0042\u0044\u0060\u006a\u005c\u0078\u0035\u0071\u002d\u0066\u007e\u0077\u004b\u0048\u006a\u007c\u0051\u0054\u003a\u004b\u0051\u005f\u002f\u0077\u007d\u0075\u0051\u002e\u002a\u0052\u004e\u003a\u002d\u007a\u007e\u0046\u0044\u0026\u0040\u006f\u0069\u004a\u002a\u007e\u0045\u0033\u0072\u0045\u0072\u0026\u004c\u0051\u0076\u0039\u0077\u0061\u002c\u0063\u0063\u004a\u007a\u0044\u0067\u002d\u006d\u002c\u007a\u003e\u0068\u004a\u0053\u004b\u0024\u0068\u0073\u002f\u007d\u005e\u005f\u0057\u005a\u0068\u0040\u006e\u0074\u0078\u002d\u0031\u003e\u0030\u003e\u006a\u0023\u007e\u003a\u005e\u0051\u007d\u004d\u0061\u0066\u0035\u004d\u0068\u004b\u007e\u0064\u0043\u004a\u0036\u0039\u002c\u004a\u0074\u0045\u003d\u0060\u007d\u004c\u003b\u003a\u0035\u0058\u007b\u0063\u0040\u0038\u0053\u0076\u0054\u004d\u0031\u004c\u0065\u0069\u007d\u0075\u0030\u0054\u0023\u0027\u0029\u006c\u0042\u004b\u0057\u005d\u0056\u0074\u007a\u005b\u0028\u006c\u0028\u0047\u007c\u0030\u0074\u0055\u003d\u002b\u002d\u0062\u003e\u0020\u006a\u0034\u0026\u0053\u006b\u0078\u0042\u0051\u007b\u005c\u0072\u0038\u005a\u0079\u0063\u0028\u0068\u0039\u0046\u0067\u0064\u007d\u007a\u0057\u0044\u004b\u006a\u007d\u0047\u0043\u0053\u007b\u006f\u007b\u0045\u0061\u006f\u0044\u006b\u0067\u005a\u0034\u0076\u0026\u004a\u0053\u0020\u0036\u0061\u0026\u006e\u0069\u0047\u002e\u0036\u0028\u0026\u007c\u0051\u004d\u0034\u0063\u0062\u005a\u0056\u002e\u005e\u0028\u0058\u0063\u006d\u0026\u006d\u0037\u0021\u0021\u005b\u0032\u005b\u0073\u007a\u003c\u0072\u0060\u006a\u0070\u004e\u004c\u0034\u0022\u0033\u0060\u0038\u005b\u0052\u005e\u0065\u0069\u003e\u0021\u0043\u006b\u0034\u0067\u007d\u0064\u0068\u006d\u0046\u0033\u002c\u0069\u003b\u004f\u002a\u0024\u006a\u0077\u0043\u0061\u002d\u0077\u006e\u0064\u0034\u0051\u005a\u005a\u0031\u004e\u0036\u0021\u0046\u004a\u0075\u0066\u005d\u0048\u0031\u0032\u003c\u0041\u0057\u0063\u0075\u003c\u007a\u005d\u0041\u004d\u006f\u0053\u003b\u0052\u002f\u0065\u006c\u0027\u006e\u006b\u004f\u003a\u0054\u003d\u0034\u0054\u0049\u0055\u0034\u0041\u002a\u0046\u0052\u0049\u0068\u0031\u002a\u0034\u0060\u0075\u002f\u006b\u0030\u005b\u002c\u0066\u004e\u0055\u0027\u0027\u0031\u0072\u0051\u002d\u005f\u004c\u0053\u0044\u007e\u0020\u0042\u0057\u005b\u0034\u007e\u0064\u0044\u006c\u007d\u002b\u0039\u0063\u007c\u004b\u005e\u0072\u0042\u0050\u0022\u003e\u006e\u003d\u006d\u0041\u0033\u0062\u0052\u004b\u0056\u0026\u006a\u0063\u007d\u0065\u007c\u0049\u0044\u0071\u004e\u006a\u003f\u002f\u0044\u0074\u0077\u006d\u005d\u0042\u0043\u004a\u007a\u003f\u0025\u0060\u0074\u0047\u004e\u003f\u0072\u002f\u0042\u002f\u0024\u002c\u005e\u0037\u0036\u003d\u0032\u005e\u0023\u0020\u003d\u007e\u0069\u002e\u0041\u0053\u0021\u003f\u0057\u0024\u0043\u007b\u0055\u0035\u007a\u0031\u0065\u0073\u0045\u0021\u0077\u002c\u0062\u0069\u007a\u002e\u0027\u0054\u0059\u007c\u0039\u0037\u0062\u0043\u0051\u0029\u004e\u0056\u0079\u0028\u0022\u002e\u003f\u0026\u0060\u0072\u0032\u0037\u004f\u0058\u0049\u0066\u0070\u0038\u007c\u005c\u0066\u0037\u0070\u002f\u002b\u006f\u0066\u004f\u0079\u004d\u0071\u0024\u0066\u005f\u0048\u0065\u0051\u007d\u0065\u002a\u0031\u0025\u0061\u0048\u0076\u004d\u006a\u0064\u0033\u0040\u003e\u0022\u0058\u006b\u0075\u0033\u004c\u0061\u003f\u002d\u0026\u0076\u0047\u004b\u0030\u005d\u002e\u0028\u007e\u005f\u0052\u0072\u0045\u006b\u0075\u0048\u0028\u002f\u0042\u0054\u0054\u0068\u0062\u0077\u0077\u0076\u0033\u0023\u0030\u003a\u007e\u003f\u0035\u006c\u005e\u0037\u002b\u003e\u003a\u006d\u0057\u0065\u0071\u0069\u006e\u002c\u007b\u0047\u005d\u0042\u005b\u007c\u0079\u006f\u0048\u004a\u0028\u0078\u0027\u0054\u0028\u006f\u0040\u0022\u003c\u0056\u0050\u0021\u007d\u004f\u0039\u0068\u0071\u004e\u0039\u0054\u005e\u0066\u002d\u002d\u0035\u0042\u003a\u0063\u003e\u0069\u002a\u005b\u007c\u003d\u0046\u006d\u0034\u003d\u007d\u002a\u0069\u0023\u0069\u004c\u003f\u0071\u0078\u0042\u002b\u006c\u004d\u0046\u007e\u005b\u0058\u0075\u0047\u0073\u0046\u0040\u005e\u007b\u003d\u004b\u0032\u0077\u0020\u005b\u003c\u0062\u005d\u007a\u007d\u006c\u0059\u0040\u0057\u0079\u0021\u007e\u0039\u0044\u0040\u004d\u0030\u0025\u0022\u0053\u005a\u002e\u002c\u0024\u0058\u004c\u0058\u0073\u0051\u004b\u006b\u0062\u0076\u0043\u0034\u004f\u0057\u0065\u0040\u0040\u0049\u0074\u004a\u006e\u004e\u0041\u005a\u0078\u0074\u0053\u0069\u002d\u0066\u006c\u007b\u003c\u0025\u0025\u0049\u0069\u0064\u004d\u007d\u002c\u0026\u0034\u0063\u0077\u0062\u0076\u0026\u0074\u0053\u0027\u0070\u0060\u006f\u0046\u005a\u0079\u0056\u005c\u007a\u0025\u002e\u0049\u0051\u0036\u007c\u0038\u0068\u0026\u004c\u003a\u004c\u005a\u0031\u006f\u0034\u004b\u0079\u0056\u0058\u003c\u003c\u003a\u004c\u0035\u0022\u0025\u0079\u0025\u005e\u007a\u0045\u0054\u0076\u0037\u0057\u005d\u0076\u0031\u005e\u006c\u0026\u007e\u0062\u0060\u0026\u007b\u0075\u0024\u0067\u0070\u0027\u0038\u0027\u0044\u003d\u003b\u0036\u0065\u0054\u003f\u003d\u0068\u002a\u0047\u0038\u0073\u007c\u0079\u002d\u003d\u0058\u0062\u0048\u004b\u002a\u006c\u007c\u0057\u0057\u003f\u004c\u003d\u0027\u0063\u003c\u004f\u0023\u0020\u007a\u005f\u0026\u0062\u0031\u0022\u0069\u006d\u003a\u0066\u0054\u007a\u002a\u0073\u0049\u007a\u0074\u0022\u006c\u0073\u0035\u005b\u0026\u0062\u0027\u002e\u002a\u0064\u0055\u0075\u0030\u0043\u0042\u0040\u004a\u007a\u0079\u0063\u005e\u0050\u004e\u0040\u005c\u002e\u0075\u0041\u0036\u0055\u0066\u004a\u006e\u0040\u0021\u004c\u0059\u0048\u006b\u003a\u0031\u0048\u004a\u006a\u002a\u0035\u0052\u007e\u0032\u0067\u006c\u0068\u0025\u0043\u0035\u0056\u0073\u0051\u0021\u0068\u003f\u005c\u0071\u0061\u002a\u0034\u0067\u0025\u002e\u0028\u002d\u006f\u003b\u0034\u003a\u0078\u0035\u0069\u0041\u0067\u0040\u0055\u004f\u0036\u0021\u0048\u0055\u004f\u007d\u0064\u0033\u002f\u004f\u006a\u005a\u002a\u006d\u0048\u005f\u0049\u002f\u0065\u0040\u0073\u004d\u004b\u006f\u002a\u0069\u0043\u0031\u003c\u0046\u0034\u0077\u0042\u006c\u0058\u0076\u005f\u0059\u004a\u0049\u006b\u0025\u003c\u0073\u0032\u004b\u0031\u0030\u0028\u007a\u0061\u003a\u007e\u0076\u0050\u0076\u007a\u005e\u004d\u0030\u005f\u0072\u0075\u0042\u0045\u0030\u0058\u004e\u0074\u0051\u003f\u0027\u0040\u0070\u004e\u0060\u0028\u003f\u0071\u005d\u0064\u0071\u003d\u0030\u0035\u002a\u0079\u0035\u0025\u004e\u004f\u0072\u0028\u0063\u0055\u0026\u004d\u006f\u006b\u0025\u0064\u0075\u0050\u0063\u0061\u003a\u0055\u005e\u0036\u003e\u004b\u0020\u005c\u003b\u007b\u005d\u0030\u006c\u006e\u0022\u0063\u005e\u0020\u0044\u003b\u0078\u002c\u002a\u0070\u0069\u003d\u003f\u0020\u002e\u003e\u0045\u0055\u0042\u0068\u002c\u0066\u0034\u005a\u003b\u0037\u003b\u003a\u0074\u0068\u0050\u002c\u005c\u0033\u0033\u0035\u0028\u002c